import java.util.*;

public class Ex10 {
    static class Engine { String name; Engine(String n){name=n;} }
    static class Container {
        Map<String, Engine> engines = new HashMap<>();
        void register(String n, Engine e){ engines.put(n, e); }
        Engine getByTypeAndName(String preferName){
            if (engines.containsKey(preferName)) return engines.get(preferName); // 按名称命中
            return engines.values().iterator().next();
        }
    }
    public static void main(String[] args) {
        Container c = new Container();
        c.register("mysql", new Engine("mysql-engine"));
        c.register("pg", new Engine("pg-engine"));
        Engine e = c.getByTypeAndName("pg");
        System.out.println("resolved: " + e.name);
        Engine e2 = c.getByTypeAndName("mysql");
        System.out.println("resolved: " + e2.name);
    }
}
